sarah: Updated snippet to handle Retry-After and backoff: ```js
// retry with Retry-After or exponential backoff
async function gen(client, opts){
  for(let i=0;i<4;i++){
    try{return await client.generate(opts);}catch(e){
      const ra=parseInt(e.headers?.['retry-after']||'0',10);
      if(ra) await new Promise(r=>setTimeout(r,ra*1000));
      else if(i<3) await new Promise(r=>setTimeout(r,Math.min(1000*2**i+Math.random()*300,8000)));
      else throw e;
    }
  }
}
```

